    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)

    def pair(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    sx, sy = pair(observation.get("self_position", (0, 0)))
    ox, oy = pair(observation.get("opponent_position", (sx, sy)), (sx, sy))

    obs = set()
    for p in observation.get("obstacles", []):
        x, y = pair(p, None)
        if x is not None:
            obs.add((x, y))

    res = []
    for p in observation.get("resources", []):
        x, y = pair(p, None)
        if x is not None:
            res.append((x, y))

    terr = []
    for p in observation.get("territory", []):
        x, y = pair(p, None)
        if x is not None:
            terr.append((x, y))

    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def ok(x, y):
        return 0 <= x < w and 0 <= y < h and (x, y) not in obs

    moves = [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]
    legal = []
    for m in moves:
        nx, ny = sx + m[0], sy + m[1]
        if ok(nx, ny):
            legal.append(m)
    if not legal:
        return [0, 0]

