    cx = (w - 1) / 2.0 if w else 0.0
    cy = (h - 1) / 2.0 if h else 0.0

    def openness(x, y):
        c = 0
        for m in moves[1:]:
            nx, ny = x + m[0], y + m[1]
            if ok(nx, ny):
                c += 1
        return c

    def score(m):
        nx, ny = sx + m[0], sy + m[1]
        d_opp = abs(nx - ox) + abs(ny - oy)
        d_ctr = abs(nx - cx) + abs(ny - cy)
        open_bonus = openness(nx, ny)
